ALTER TABLE agenda_events ADD COLUMN status "TaskStatus" NOT NULL DEFAULT 'TODO', ADD COLUMN assignee_id uuid, ADD COLUMN completed_at timestamptz(3);
CREATE INDEX agenda_events_org_status_idx ON agenda_events (organization_id, status, starts_at);
CREATE TABLE activity_checklists (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, activity_kind text NOT NULL CHECK (activity_kind IN ('TASK','EVENT','DEADLINE')), activity_id uuid NOT NULL, title text NOT NULL, created_at timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,organization_id));
CREATE INDEX activity_checklists_target_idx ON activity_checklists(organization_id,activity_kind,activity_id);
CREATE TABLE activity_checklist_items (id uuid PRIMARY KEY, organization_id uuid NOT NULL, checklist_id uuid NOT NULL, body text NOT NULL, done boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, updated_at timestamptz(3) NOT NULL, FOREIGN KEY(checklist_id,organization_id) REFERENCES activity_checklists(id,organization_id) ON DELETE CASCADE);
CREATE INDEX activity_checklist_items_parent_idx ON activity_checklist_items(organization_id,checklist_id);
CREATE TABLE activity_collaborators (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, activity_kind text NOT NULL CHECK(activity_kind IN ('TASK','EVENT','DEADLINE')), activity_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,activity_kind,activity_id,user_id));
CREATE TABLE activity_series (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, activity_kind text NOT NULL CHECK(activity_kind IN ('TASK','EVENT')), rule jsonb NOT NULL, created_by_id uuid NOT NULL REFERENCES users(id), created_at timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,organization_id));
CREATE INDEX activity_series_org_idx ON activity_series(organization_id);
CREATE TABLE activity_occurrences (id uuid PRIMARY KEY, organization_id uuid NOT NULL, series_id uuid NOT NULL, activity_kind text NOT NULL CHECK(activity_kind IN ('TASK','EVENT')), activity_id uuid NOT NULL, date date NOT NULL, FOREIGN KEY(series_id,organization_id) REFERENCES activity_series(id,organization_id) ON DELETE CASCADE, UNIQUE(organization_id,activity_kind,activity_id), UNIQUE(series_id,date));

ALTER TABLE workflow_package_steps ADD COLUMN count_type text NOT NULL DEFAULT 'CALENDAR' CHECK(count_type IN ('CALENDAR','BUSINESS')), ADD COLUMN relative_to text NOT NULL DEFAULT 'BASE' CHECK(relative_to IN ('BASE','PREVIOUS_DUE','PREVIOUS_DONE')), ADD COLUMN wait_for_previous boolean NOT NULL DEFAULT false, ADD COLUMN assignee_mode text NOT NULL DEFAULT 'TRIGGER_USER' CHECK(assignee_mode IN ('TRIGGER_USER','CASE_RESPONSIBLE','FIXED'));
UPDATE workflow_package_steps SET assignee_mode = 'FIXED' WHERE assignee_id IS NOT NULL;
CREATE TABLE task_dependencies(id uuid PRIMARY KEY,organization_id uuid NOT NULL,task_id uuid NOT NULL UNIQUE,predecessor_id uuid NOT NULL,offset_days integer NOT NULL DEFAULT 0,count_type text NOT NULL DEFAULT 'CALENDAR' CHECK(count_type IN ('CALENDAR','BUSINESS')),on_completion boolean NOT NULL DEFAULT false,non_working_dates text[] NOT NULL DEFAULT '{}',FOREIGN KEY(task_id,organization_id) REFERENCES tasks(id,organization_id) ON DELETE CASCADE,FOREIGN KEY(predecessor_id,organization_id) REFERENCES tasks(id,organization_id) ON DELETE CASCADE,CHECK(task_id<>predecessor_id));
CREATE INDEX task_dependencies_predecessor_idx ON task_dependencies(organization_id,predecessor_id);
